<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="page"><h1>Categories</h1><form class="admin-form" method="get" action="<?= site_url('admin/categories') ?>"><label>Search categories<input name="q" type="search" value="<?= esc($query) ?>"></label><button type="submit">Search</button></form><?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?><?php if (session('success')): ?><p role="status"><?= esc(session('success')) ?></p><?php endif ?>
